using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Globalization;using System.Windows.Forms;
internal sealed class StudioColorPicker:Form{
 readonly SvCanvas square=new SvCanvas();readonly HueCanvas hue=new HueCanvas();readonly TextBox hex=new TextBox();readonly NumericUpDown[] rgb=new NumericUpDown[3];readonly Panel sample=new Panel();Button confirm;bool sync;Color color=Color.FromArgb(212,47,55);public bool FullOpen{get;set;}
 internal static string[] ImageColors=new string[0];
 public Color Color{get{return color;}set{color=value;UpdateFields();}}
 public StudioColorPicker(){Text="颜色编辑器";Font=new Font("Microsoft YaHei UI",10);ClientSize=new Size(620,452);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=MinimizeBox=false;StartPosition=FormStartPosition.CenterParent;BackColor=StudioUi.Paper;Controls.Add(StudioUi.Label("自由选色",new Rectangle(24,20,500,32),18,true));Controls.Add(StudioUi.Label("拖动色板或色相条，也可以直接输入色值。",new Rectangle(24,60,560,26),9));square.SetBounds(24,102,350,230);hue.SetBounds(24,348,350,20);Controls.Add(square);Controls.Add(hue);sample.SetBounds(404,102,190,54);Controls.Add(sample);hex.SetBounds(404,171,190,28);Controls.Add(hex);hex.AccessibleName="HEX 色值";hex.MaxLength=7;hex.CharacterCasing=CharacterCasing.Upper;hex.TextChanged+=delegate{if(sync)return;string t=hex.Text.Trim();if(Palette.IsColor(t)){color=ColorTranslator.FromHtml(t);UpdateFields();}else{hex.BackColor=Color.MistyRose;if(confirm!=null)confirm.Enabled=false;}};for(int i=0;i<3;i++){int index=i;Controls.Add(StudioUi.Label(new[]{"R","G","B"}[i],new Rectangle(404,214+i*37,24,26),10));rgb[i]=new NumericUpDown{Minimum=0,Maximum=255,Location=new Point(439,211+i*37),Size=new Size(155,28),AccessibleName=new[]{"红色通道","绿色通道","蓝色通道"}[i]};Controls.Add(rgb[i]);rgb[i].ValueChanged+=delegate{if(!sync){color=Color.FromArgb((int)rgb[0].Value,(int)rgb[1].Value,(int)rgb[2].Value);UpdateFields();}};}
  square.Changed+=delegate{color=Hsv(hue.Hue,square.Saturation,square.Value);UpdateFields(false);};hue.Changed+=delegate{square.Hue=hue.Hue;color=Hsv(hue.Hue,square.Saturation,square.Value);UpdateFields(false);};var chips=ImageColors.Length>0?ImageColors:new[]{"#D52F37","#F09A8A","#E9D8BC","#207F77","#3D6FD5","#212A31"};for(int i=0;i<Math.Min(12,chips.Length);i++){string chosen=chips[i];var b=StudioUi.Button("",new Rectangle(404+i%6*32,332+i/6*30,26,26));b.BackColor=ColorTranslator.FromHtml(chosen);b.AccessibleName="图片颜色 "+chosen;b.Click+=delegate{Color=ColorTranslator.FromHtml(chosen);};Controls.Add(b);}var cancel=StudioUi.Button("取消",new Rectangle(370,398,100,36));cancel.DialogResult=DialogResult.Cancel;confirm=StudioUi.Button("使用此颜色",new Rectangle(482,398,112,36),true);confirm.DialogResult=DialogResult.OK;Controls.Add(cancel);Controls.Add(confirm);AcceptButton=confirm;CancelButton=cancel;UpdateFields();}
 void UpdateFields(bool updateHsv=true){if(rgb[0]==null)return;sync=true;if(confirm!=null)confirm.Enabled=true;hex.Text=SmartPalette.Hex(color);hex.BackColor=Color.FromArgb(251,252,252);rgb[0].Value=color.R;rgb[1].Value=color.G;rgb[2].Value=color.B;sample.BackColor=color;if(updateHsv){double max=Math.Max(color.R,Math.Max(color.G,color.B))/255d,min=Math.Min(color.R,Math.Min(color.G,color.B))/255d;hue.Hue=color.GetHue();square.Hue=hue.Hue;square.Saturation=max==0?0:(max-min)/max;square.Value=max;}square.Invalidate();hue.Invalidate();sync=false;}
 internal static Color Hsv(double h,double s,double v){h=(h%360+360)%360;double c=v*s,x=c*(1-Math.Abs(h/60%2-1)),m=v-c,r=0,g=0,b=0;if(h<60){r=c;g=x;}else if(h<120){r=x;g=c;}else if(h<180){g=c;b=x;}else if(h<240){g=x;b=c;}else if(h<300){r=x;b=c;}else{r=c;b=x;}return Color.FromArgb((int)Math.Round((r+m)*255),(int)Math.Round((g+m)*255),(int)Math.Round((b+m)*255));}
 internal void RenderForTest(string path){StartPosition=FormStartPosition.Manual;Location=new Point(-30000,-30000);ShowInTaskbar=false;Show();Application.DoEvents();using(var b=new Bitmap(Width,Height)){DrawToBitmap(b,new Rectangle(0,0,Width,Height));b.Save(path);}Close();}
}
internal sealed class SvCanvas:Control{
 internal double Hue,Saturation=1,Value=1;internal event EventHandler Changed;Bitmap cache;double cachedHue=-1;
 internal SvCanvas(){DoubleBuffered=true;Cursor=Cursors.Cross;AccessibleName="饱和度与明度色板";}
 protected override void OnPaint(PaintEventArgs e){if(cache==null||cachedHue!=Hue){if(cache!=null)cache.Dispose();cache=new Bitmap(256,180);for(int y=0;y<180;y++)for(int x=0;x<256;x++)cache.SetPixel(x,y,StudioColorPicker.Hsv(Hue,x/255d,1-y/179d));cachedHue=Hue;}e.Graphics.DrawImage(cache,ClientRectangle);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;float px=(float)Math.Max(6,Math.Min(Width-6,Saturation*(Width-1))),py=(float)Math.Max(6,Math.Min(Height-6,(1-Value)*(Height-1)));using(var pen=new Pen(Color.FromArgb(40,50,55),4))e.Graphics.DrawEllipse(pen,px-5,py-5,10,10);using(var pen=new Pen(Color.White,2))e.Graphics.DrawEllipse(pen,px-5,py-5,10,10);}
 void Pick(MouseEventArgs e){Saturation=Math.Max(0,Math.Min(1,e.X/(double)Math.Max(1,Width-1)));Value=1-Math.Max(0,Math.Min(1,e.Y/(double)Math.Max(1,Height-1)));Invalidate();if(Changed!=null)Changed(this,EventArgs.Empty);}
 protected override bool IsInputKey(Keys k){return k==Keys.Left||k==Keys.Right||k==Keys.Up||k==Keys.Down||base.IsInputKey(k);}
 protected override void OnKeyDown(KeyEventArgs e){double step=e.Shift?.05:.01;if(e.KeyCode==Keys.Left)Saturation-=step;else if(e.KeyCode==Keys.Right)Saturation+=step;else if(e.KeyCode==Keys.Up)Value+=step;else if(e.KeyCode==Keys.Down)Value-=step;else{base.OnKeyDown(e);return;}Saturation=Math.Max(0,Math.Min(1,Saturation));Value=Math.Max(0,Math.Min(1,Value));Invalidate();if(Changed!=null)Changed(this,EventArgs.Empty);e.Handled=true;}
 protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);Focus();Capture=true;Pick(e);}protected override void OnMouseMove(MouseEventArgs e){if(Capture)Pick(e);}protected override void OnMouseUp(MouseEventArgs e){Capture=false;base.OnMouseUp(e);}protected override void Dispose(bool d){if(d&&cache!=null)cache.Dispose();base.Dispose(d);}
}
internal sealed class HueCanvas:Control{
 internal double Hue;internal event EventHandler Changed;internal HueCanvas(){DoubleBuffered=true;Cursor=Cursors.Hand;AccessibleName="色相";}
 protected override void OnPaint(PaintEventArgs e){for(int x=0;x<Width;x++)using(var p=new Pen(StudioColorPicker.Hsv(x*360d/Width,1,1)))e.Graphics.DrawLine(p,x,0,x,Height);int px=(int)Math.Max(4,Math.Min(Width-5,Hue/360*(Width-1)));using(var p=new Pen(Color.White,3))e.Graphics.DrawRectangle(p,px-3,1,6,Height-3);}
 void Pick(MouseEventArgs e){Hue=Math.Max(0,Math.Min(359.9,e.X*360d/Math.Max(1,Width)));Invalidate();if(Changed!=null)Changed(this,EventArgs.Empty);}protected override void OnMouseDown(MouseEventArgs e){Focus();Capture=true;Pick(e);}protected override void OnMouseMove(MouseEventArgs e){if(Capture)Pick(e);}protected override void OnMouseUp(MouseEventArgs e){Capture=false;}
}
